// Translations of the long-form editorial bios in lib/philosopher-bios.ts
// (PHILOSOPHER_BIOS), keyed by slug → locale → translated essay. Used by
// /philosopher/[slug] to render the "ABOUT" bio in the reader's locale.
//
// Unlike the other content overlays (whose entries are field objects), each
// bio is a single flat string, so the per-locale value here is the whole
// translated essay — shape Record<slug, Partial<Record<Locale, string>>>.
//
// The PHILOSOPHER_BIOS_I18N block between the sentinels is GENERATED by
// scripts/translate-content.mjs (domain "philosopherBios") — don't hand-edit
// inside them. The helper below is hand-maintained. English is the source
// (lives in PHILOSOPHER_BIOS), so a missing locale falls back to English at
// the call site.
//
// Each bio is a multi-paragraph essay; the renderer splits on the blank line
// ("\n\n") between paragraphs, so translations must preserve those breaks.

import type { Locale } from './translations';

